func TestRawClient_Do_RetriesSeekableReaderBody(t *testing.T) {
	t.Parallel()

	var mu sync.Mutex
	var bodies []string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			t.Errorf("read request body: %v", err)
			return
		}
		mu.Lock()
		bodies = append(bodies, string(body))
		attempt := len(bodies)
		mu.Unlock()

		if attempt == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"message":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	httpClient := NewHTTPClient(Config{
		HTTPClient:  srv.Client(),
		RetryPolicy: &RetryPolicy{MaxAttempts: 2},
	})

	raw, err := NewRawClient(srv.URL, httpClient)
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	file := tempFileWithContent(t, "upload payload")

	var out struct {
		Ok bool `json:"ok"`
	}
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, file, &out); err != nil {
		t.Fatalf("Do error: %v", err)
	}
	if !out.Ok {
		t.Fatalf("expected ok=true")
	}

	mu.Lock()
	defer mu.Unlock()
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	for i, body := range bodies {
		if body != "upload payload" {
			t.Fatalf("attempt %d sent %q, want %q", i+1, body, "upload payload")
		}
	}
}

func TestRawClient_Do_DoesNotCloseSeekableReaderBody(t *testing.T) {
	t.Parallel()

	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = io.Copy(io.Discard, r.Body)
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"ok":true}`))
	}))
	t.Cleanup(srv.Close)

	raw, err := NewRawClient(srv.URL, srv.Client())
	if err != nil {
		t.Fatalf("NewRawClient error: %v", err)
	}

	file := tempFileWithContent(t, "payload")
	if err := raw.Do(context.Background(), http.MethodPost, "/files", nil, file, nil); err != nil {
		t.Fatalf("Do error: %v", err)
	}

	// The caller owns the reader: it must still be usable (and closable)
	// after the request, so a retry can rewind it.
	if _, err := file.Seek(0, io.SeekStart); err != nil {
		t.Fatalf("seek after request: %v", err)
	}
	if err := file.Close(); err != nil {
		t.Fatalf("close after request: %v", err)
	}
}

