func TestFilesService_Add_RetriesRateLimitedFileUpload(t *testing.T) {
	t.Parallel()

	contentType := "multipart/form-data; boundary=test"
	var mu sync.Mutex
	var bodies []string

	policy := pipedrive.DefaultRetryPolicy()
	policy.MaxAttempts = 2
	policy.BaseDelay = 0

	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
