	f(cfg)
}

func WithFilesQuery(values url.Values) FilesRequestOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.query = mergeQueryValues(cfg.query, values)
	})
}

func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesRequestOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.requestOptions = append(cfg.requestOptions, opts...)
	})
}

// WithFileFormValue sets a raw multipart form field on an upload, for
// fields the typed options do not cover yet.
func WithFileFormValue(key, value string) UploadFileOption {
	return uploadFileOptionFunc(func(cfg *uploadFileOptions) {
		if key == "" {
			return
		}
		if cfg.form == nil {
			cfg.form = url.Values{}
		}
		cfg.form.Set(key, value)
	})
}

