new_add = '''// Upload adds a file, encoding the multipart/form-data body from a file
// name and a reader over the content. Associate the file with a record
// through options such as WithFileDealID.
//
// The content is buffered while it is encoded, so the request body is
// replayable and a rate-limited or failed upload is retried under the
// configured retry policy. Use Add instead to stream a body you have
// encoded yourself.
func (s *FilesService) Upload(ctx context.Context, fileName string, content io.Reader, opts ...UploadFileOption) (*File, error) {
	cfg := newUploadFileOptions(opts)
	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("file content is required")
	}

	contentType, body, err := multipartbody.NewFileWithFields("file", fileName, content, cfg.form)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
