+// os.Open arrives without one and the retry transport has to treat the
+// request as unreplayable: file uploads fail on the first 429 while every
+// other call retries.
+//
+// A reader that can seek needs no buffering, because rewinding to the
+// offset the body started at reproduces it byte for byte. Such a body is
+// also wrapped so the transport cannot close it: a closed reader cannot be
+// rewound for the next attempt, and the caller owns the reader it passed
+// in. A reader that cannot seek is streamed exactly once, as before.
+func makeBodyReplayable(req *http.Request, body io.Reader) {
+	if body == nil || req.Body == nil || req.GetBody != nil {
+		return
+	}
+	seeker, ok := body.(io.Seeker)
+	if !ok {
+		return
+	}
+	start, err := seeker.Seek(0, io.SeekCurrent)
+	if err != nil {
+		// Implementing io.Seeker does not guarantee a seekable stream;
+		// an *os.File over a pipe is one example. Keep streaming the
+		// body once instead of failing a request that would succeed.
+		return
+	}
+
+	req.Body = io.NopCloser(body)
+	req.GetBody = func() (io.ReadCloser, error) {
+		if _, err := seeker.Seek(start, io.SeekStart); err != nil {
+			return nil, fmt.Errorf("rewind request body: %w", err)
+		}
+		return io.NopCloser(body), nil
+	}
+}

